// One message a week listing every application that is still open, so a reviewer can see
// the whole queue at once and jump into a thread from it. It reads the table and posts,
// and that is all: no row is changed, no model is called and no applicant is emailed.
//
// The collective's name is the applicant's own text, so it is data, not markup: a name
// like <!channel> would otherwise be honoured by Slack in the reviewers' channel. Escape
// the three characters Slack treats as control characters, & first so the other two are
// not escaped twice. The fixed wording is left alone so it keeps its *bold* and emoji.
const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const channel = $env.SLACK_CHANNEL || '';
if (!channel) throw new Error('weekly digest: SLACK_CHANNEL is empty');
// A typo here must not switch the warning off without a word, so anything that is not a
// number of days falls back to the default.
const staleSetting = Number($env.DIGEST_STALE_DAYS || 7);
const staleDays = Number.isFinite(staleSetting) && staleSetting >= 0 ? staleSetting : 7;

// auth.test names the workspace, which is the one part of a thread link the row does not
// hold. A failed lookup costs the links and nothing else, so the digest still posts. The
// address is checked with a regex because the sandbox has no URL global, and anything
// other than a plain workspace address is not used to build a link.
const auth = $('Look up the Slack workspace').first().json;
const workspace = auth && auth.ok === true && typeof auth.url === 'string'
  && /^https:\/\/[a-z0-9-]+\.slack\.com\/$/.test(auth.url) ? auth.url : '';

const TERMINAL = new Set(['approved', 'rejected', 'resigned']);
// Get open rows always outputs, so an empty table still reaches this node as one empty
// item. Dropping rows without a slug removes it, and the terminal check repeats the
// node's own filter so a change there cannot put a closed application in the digest.
const rows = $input.all().map((item) => item.json)
  .filter((row) => row.slug && !TERMINAL.has(row.stage));

const daysSince = (value) => {
  if (!value) return null;
  const then = DateTime.fromJSDate(new Date(value));
  if (!then.isValid) return null;
  return Math.max(0, Math.floor($now.diff(then, 'days').days));
};
const ago = (days) => days === 0 ? 'today' : days === 1 ? '1 day ago' : `${days} days ago`;

const link = (row) => {
  const name = escapeSlack(row.collective_name || row.slug);
  const ts = String(row.slack_thread_ts || '');
  const channelId = String(row.slack_channel_id || '');
  if (!workspace || !/^[CGD][A-Z0-9]+$/.test(channelId) || !/^\d+\.\d+$/.test(ts)) return `*${name}*`;
  return `<${workspace}archives/${channelId}/p${ts.replace('.', '')}|${name}>`;
};

// Each stage lands in the group of whoever has the next move. `waited` is how long the
// row has been in that state, which orders the group oldest first and, for the rows that
// are with OSE, decides the warning.
const describe = (row) => {
  const invited = daysSince(row.form_invited_at);
  const reminded = daysSince(row.form_reminded_at);
  switch (row.stage) {
    case 'form_submitted':
    case 'awaiting_decision': {
      const waited = daysSince(row.form_submitted_at);
      return { group: 'ose', waited, text: waited === null ? 'form sent' : `form sent ${ago(waited)}` };
    }
    case 'escalated': {
      const waited = daysSince(row.slack_notified_at);
      return { group: 'ose', waited,
        text: waited === null ? 'no form after the reminder, escalated'
          : `no form after the reminder, escalated ${ago(waited)}` };
    }
    case 'form_invited':
      return { group: 'applicant', waited: invited,
        text: [invited === null ? 'invited' : `invited ${ago(invited)}`,
          reminded === null ? null : `reminded ${ago(reminded)}, no form yet`].filter(Boolean).join(', ') };
    case 'form_started':
      return { group: 'applicant', waited: invited,
        text: invited === null ? 'started the form, not sent' : `started the form, not sent, invited ${ago(invited)}` };
    case 'applied': {
      const waited = daysSince(row.applied_at);
      return { group: 'pipeline', waited,
        text: waited === null ? 'AI review pending' : `applied ${ago(waited)}, AI review pending` };
    }
    case 'reviewed':
      // apply 3 found a decision on Open Collective before it could invite, so no
      // invitation is coming and the decision sweep records the outcome next.
      if (row.form_invite_skipped_at) {
        return { group: 'pipeline', waited: daysSince(row.form_invite_skipped_at),
          text: 'decided on Open Collective before the invitation, not yet recorded' };
      }
      return { group: 'pipeline', waited: daysSince(row.ai_reviewed_at), text: 'reviewed, invitation pending' };
    default:
      return { group: 'pipeline', waited: null, text: `stage ${escapeSlack(row.stage || 'unknown')}` };
  }
};

const GROUPS = [
  ['ose', 'Waiting for an OSE decision'],
  ['applicant', 'Waiting for the applicant'],
  ['pipeline', 'In the pipeline'],
];

// A week with nothing open still posts, so a quiet Friday reads as an empty queue and not
// as a digest that failed to run.
if (rows.length === 0) {
  const empty = { json: { channel, text: ':clipboard: *Open applications*: nothing open this week' } };
  return empty;
}

const described = rows.map((row) => ({ row, ...describe(row) }));
const sections = GROUPS.map(([key, title]) => {
  const members = described.filter((entry) => entry.group === key)
    .sort((a, b) => (b.waited ?? -1) - (a.waited ?? -1));
  if (members.length === 0) return null;
  const lines = members.map((entry) => {
    const warn = key === 'ose' && entry.waited !== null && entry.waited > staleDays ? ' :warning:' : '';
    return `• ${link(entry.row)} · ${entry.text}${warn}`;
  });
  const block = [`*${title}* (${members.length})`, ...lines];
  return block.join('\n');
}).filter(Boolean);

const text = [`:clipboard: *Open applications* (${rows.length} open)`, ...sections].join('\n\n');
const digest = { json: { channel, text } };
return digest;
